import { openDB } from 'idb';

const DB_NAME = 'leetcode-tracker';
const DB_VERSION = 1;
const STORE_NAME = 'questions';

function getDB() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    },
  });
}

export async function getAllQuestions() {
  const db = await getDB();
  return db.getAll(STORE_NAME);
}

export async function saveAllQuestions(questions) {
  const db = await getDB();
  const tx = db.transaction(STORE_NAME, 'readwrite');
  await tx.store.clear();
  for (const q of questions) {
    await tx.store.put(q);
  }
  await tx.done;
}

// Migrate existing localStorage data to IndexedDB (one-time)
export async function migrateFromLocalStorage() {
  const stored = localStorage.getItem('leetcode-questions');
  if (stored) {
    try {
      const questions = JSON.parse(stored);
      if (Array.isArray(questions) && questions.length > 0) {
        await saveAllQuestions(questions);
        localStorage.removeItem('leetcode-questions');
      }
    } catch {
      // ignore parse errors
    }
  }
}
